var e={rules:{intro:{t:0,b:{t:2,i:[{t:3}],s:`Автоматизуйте принтер за допомогою безпечних правил «якщо - то». Вимкнено за замовчуванням; кожне правило вмикайте самостійно.`}},empty:{t:0,b:{t:2,i:[{t:3}],s:`Правил ще немає. Додайте одне нижче, а потім увімкніть, коли будете готові.`}},engine:{on:{t:0,b:{t:2,i:[{t:3}],s:`Рушій правил УВІМКНЕНО`}},off:{t:0,b:{t:2,i:[{t:3}],s:`Рушій правил ВИМКНЕНО`}},turnOn:{t:0,b:{t:2,i:[{t:3}],s:`Увімкнути`}},turnOff:{t:0,b:{t:2,i:[{t:3}],s:`Вимкнути`}},masterNote:{t:0,b:{t:2,i:[{t:3}],s:`Нічого не виконається, доки не ввімкнено і рушій, і саме правило.`}}},triggers:{print_complete:{t:0,b:{t:2,i:[{t:3}],s:`Коли друк завершується`}},print_error:{t:0,b:{t:2,i:[{t:3}],s:`Коли в принтері виникає помилка`}},temp_above:{t:0,b:{t:2,i:[{t:3}],s:`Коли нагрівач піднімається вище`}},temp_below:{t:0,b:{t:2,i:[{t:3}],s:`Коли нагрівач опускається нижче`}}},actions:{notify:{t:0,b:{t:2,i:[{t:3}],s:`Записати сповіщення`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`Виконати команду g-code`}}},rule:{armed:{t:0,b:{t:2,i:[{t:3}],s:`Увімкнено`}},arm:{t:0,b:{t:2,i:[{t:3}],s:`Вимкнено`}},edit:{t:0,b:{t:2,i:[{t:3}],s:`Редагувати`}},delete:{t:0,b:{t:2,i:[{t:3}],s:`Видалити`}},confirmDelete:{t:0,b:{t:2,i:[{t:3}],s:`Видалити правило`}}},form:{name:{t:0,b:{t:2,i:[{t:3}],s:`Назва правила`}},namePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`напр. Вимкнути нагрівачі після друку`}},trigger:{t:0,b:{t:2,i:[{t:3}],s:`Якщо (тригер)`}},action:{t:0,b:{t:2,i:[{t:3}],s:`То (дія)`}},heater:{t:0,b:{t:2,i:[{t:3}],s:`Нагрівач`}},value:{t:0,b:{t:2,i:[{t:3}],s:`Температура (°C)`}},message:{t:0,b:{t:2,i:[{t:3}],s:`Повідомлення`}},messagePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`Показується в журналі правил`}},gcode:{t:0,b:{t:2,i:[{t:3}],s:`G-code`}},gcodePlaceholder:{t:0,b:{t:2,i:[{t:3}],s:`напр. TURN_OFF_HEATERS`}},save:{t:0,b:{t:2,i:[{t:3}],s:`Зберегти правило`}},cancel:{t:0,b:{t:2,i:[{t:3}],s:`Скасувати`}},add:{t:0,b:{t:2,i:[{t:3}],s:`Додати правило`}}},log:{title:{t:0,b:{t:2,i:[{t:3}],s:`Нещодавня активність`}},outcome:{notify:{t:0,b:{t:2,i:[{t:3}],s:`сповіщено`}},ran:{t:0,b:{t:2,i:[{t:3}],s:`виконано g-code`}},skipped_busy:{t:0,b:{t:2,i:[{t:3}],s:`пропущено (принтер зайнятий)`}},error:{t:0,b:{t:2,i:[{t:3}],s:`помилка`}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:`Довідка`}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:`Довідник із рушія правил`}},close:{t:0,b:{t:2,i:[{t:3}],s:`Закрити`}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:`Що таке рушій правил?`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Він стежить за принтером і виконує дію, коли виконується задана вами умова - наприклад, записати нотатку після завершення друку або вимкнути нагрівачі. Кожне правило має вигляд: ЯКЩО (тригер), ТО (дія).`}}},safety:{title:{t:0,b:{t:2,i:[{t:3}],s:`Як він залишається безпечним`}},body:{t:0,b:{t:2,i:[{t:3}],s:`Рушій вимкнено за замовчуванням, і кожне правило потрібно вмикати окремо, тож нічого не спрацює несподівано. Правило виконується один раз, коли його умова вперше стає істинною. Дії g-code виконуються лише тоді, коли принтер не зайнятий - під час друку вони відхиляються - і кожен результат записується.`}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:`Глосарій`}}}},glossary:{trigger:{term:{t:0,b:{t:2,i:[{t:3}],s:`Тригер`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Умова, що запускає правило, напр. завершення друку або перетин нагрівачем певної температури.`}}},action:{term:{t:0,b:{t:2,i:[{t:3}],s:`Дія`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Що робить правило, коли спрацьовує: записати сповіщення або виконати команду g-code (лише коли принтер не зайнятий).`}}},armed:{term:{t:0,b:{t:2,i:[{t:3}],s:`Увімкнено`}},def:{t:0,b:{t:2,i:[{t:3}],s:`Правило, яке ввімкнено. Вимкнені правила зберігаються, але ніколи не спрацьовують.`}}}}}}};export{e as default};